using System;using System.IO;using System.Linq;using System.Drawing;using System.Reflection;using System.Collections.Generic;using System.Windows.Forms;using System.Xml.Serialization;using MakroSoundSwitch;
class SortToggleVerify {
 static BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Assert(bool ok,string message){if(!ok)throw new Exception(message);Console.WriteLine("PASS: "+message);}
 [STAThread]static void Main(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);
 Assert(Media.Command(FeatureType.PlayPauseMedia)==14&&Media.Command(FeatureType.PlayMedia)==14&&Media.Command(FeatureType.PauseMedia)==14,"New and existing playback actions use Windows play/pause toggle");bool playing=false;foreach(var type in new[]{FeatureType.PlayPauseMedia,FeatureType.PlayMedia,FeatureType.PauseMedia}){if(Media.Command(type)==14)playing=!playing;}Assert(playing,"Toggle resumes paused media and pauses playing media");
 var scenario=new Scenario{Name="Sorted setup",Chord=new List<int>{17,18,16,75,76},Features=new List<ScenarioFeature>{new ScenarioFeature{Type=FeatureType.PlayMedia},new ScenarioFeature{Type=FeatureType.NextMedia},new ScenarioFeature{Type=FeatureType.MuteMedia}}};
 using(var editor=new Editor(scenario,new List<Scenario>{scenario})){editor.Show();Application.DoEvents();var keys=(ScenarioList)typeof(Editor).GetField("keyRows",F).GetValue(editor);var features=(ScenarioList)typeof(Editor).GetField("featureRows",F).GetValue(editor);var lastKey=keys.Controls[keys.Controls.Count-1];
 typeof(ScenarioList).GetField("draggingRow",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,lastKey);var data=new DataObject("Text","plain drag text");var target=keys.PointToScreen(new Point(10,keys.Controls[0].Top+1));var drag=new DragEventArgs(data,1,target.X,target.Y,DragDropEffects.Move,DragDropEffects.None);typeof(ScenarioList).GetMethod("OnDragEnter",F).Invoke(keys,new object[]{drag});Assert(drag.Effect==DragDropEffects.Move,"Key list accepts a drag from its own handle row");typeof(ScenarioList).GetMethod("OnDragOver",F).Invoke(keys,new object[]{drag});typeof(ScenarioList).GetMethod("OnDragDrop",F).Invoke(keys,new object[]{drag});Assert(keys.Controls[0]==lastKey,"Dragging last key to first changes visible key order");var selectors=(List<ComboBox>)typeof(Editor).GetField("keySelectors",F).GetValue(editor);Assert(((KeyItem)selectors[0].SelectedItem).Value==76,"Key order data synchronizes after drag/drop");
 var lastFeature=features.Controls[features.Controls.Count-1];typeof(ScenarioList).GetField("draggingRow",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,lastFeature);data=new DataObject("MakroSoundSwitch.Row",lastFeature);target=features.PointToScreen(new Point(10,features.Controls[0].Top+1));drag=new DragEventArgs(data,1,target.X,target.Y,DragDropEffects.Move,DragDropEffects.None);typeof(ScenarioList).GetMethod("OnDragDrop",F).Invoke(features,new object[]{drag});Assert(features.Controls[0]==lastFeature,"Dragging last feature to first changes feature order");typeof(ScenarioList).GetField("draggingRow",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,lastKey);var cross=new DragEventArgs(new DataObject("MakroSoundSwitch.Row",lastKey),1,target.X,target.Y,DragDropEffects.Move,DragDropEffects.Move);typeof(ScenarioList).GetMethod("OnDragEnter",F).Invoke(features,new object[]{cross});Assert(cross.Effect==DragDropEffects.None,"Keys cannot accidentally be dropped into the feature list");
 typeof(ScenarioList).GetField("draggingRow",BindingFlags.Static|BindingFlags.NonPublic).SetValue(null,null);var featureRows=(List<FeatureRow>)typeof(Editor).GetField("featureSelectors",F).GetValue(editor);Assert(featureRows[1].Value.Type==FeatureType.PlayPauseMedia,"Existing Play action edits as combined play/pause feature");typeof(Editor).GetMethod("Save",F).Invoke(editor,new object[]{null,EventArgs.Empty});Assert(editor.Result.Chord.SequenceEqual(new[]{76,17,18,16,75}),"Saved shortcut retains dragged key order");Assert(editor.Result.Features.Select(f=>f.Type).SequenceEqual(new[]{FeatureType.MuteMedia,FeatureType.PlayPauseMedia,FeatureType.NextMedia}),"Saved features retain dragged execution order");using(var stream=new MemoryStream()){var serializer=new XmlSerializer(typeof(Scenario));serializer.Serialize(stream,editor.Result);stream.Position=0;var loaded=(Scenario)serializer.Deserialize(stream);Assert(loaded.Chord[0]==76&&loaded.Features[0].Type==FeatureType.MuteMedia,"Sorted orders persist across XML save and reload");}using(var bitmap=new Bitmap(editor.Width,editor.Height)){editor.DrawToBitmap(bitmap,new Rectangle(Point.Empty,editor.Size));bitmap.Save("sorted-editor.png");}editor.Close();}
 using(var form=new MainForm(Path.GetFullPath("no-settings-here.xml"),true)){form.ShowWindow();Application.DoEvents();Assert(form.Text=="Makro Sound Switch V.0.1","Main window has the requested app name");var tray=(NotifyIcon)typeof(MainForm).GetField("tray",F).GetValue(form);Assert(tray.Text==form.Text,"Tray icon uses the requested app name");using(var bitmap=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bitmap,new Rectangle(Point.Empty,form.Size));bitmap.Save("renamed-main.png");}}
 }
}


